1	// SCRATCHPAD JIT DRIVER (NOT a committed-source edit): generalizes
2	// mega_decoder_real_adamw_tc.cu's `tc_train_step` to dispatch over OptId via a
3	// runtime `opt_id`, exactly as the OptId-generic launcher
4	// mega_decoder_real_adamw_tc_launcher.cu does — but with its OWN pybind module so
5	// cpp_extension.load can drive it directly (the launcher TU has no pybind; it is
6	// globbed into _ops). Build-via-include only: compiled against the flagship layout
7	// with the SAME -D flags + -include decoder_flagship_layout.cuh as flagship_train.py.
8	//
9	// Scope: the SINGLE-LAUNCH ELEMENTWISE optimizers the launcher routes WITHOUT extra
10	// state plumbing over the plain [m|v|extra] (3*total) buffer:
11	//   AdamW(0), Lion(1), Grokfast(2), GrokAdamW(3), NeuralGrok(6)
12	// (Prodigy/Muon/LookSAM/SG11/SG15 need an EXTENDED state buffer + extra device packs;
13	// SG2 needs ncta=1 + a meta-net weight bundle. Those are intentionally out of scope
14	// here — see the launcher's state-binding block.)
15	//
16	// State layout mirrors the launcher: state = [m | v | extra] (3*total); the
17	// NeuralGrok psi-net pack rides the head of the `extra` slice (kPsiW1Off/...).
18	// Scalars are passed through FusedScalars so the optimizer math is LIVE (bc1/bc2,
19	// alpha/lamb/gamma — not the inert struct defaults).
20	
21	#define SG_TUNED_GEMM_IMPL 1   // select the wgmma cell driver
22	
