31	namespace dec = ::sg::fused::sm90::dec;
32	using ::sg::fused::PersistentContext;
33	using ::sg::fused::sm90::DecoderTokenCtx;
34	using ::sg::fused::sm90::FusedOptState;
35	using ::sg::fused::sm90::FusedScalars;
36	using ::sg::fused::sm90::OptId;
37	using ::sg::fused::sm90::kDecTotalElems;
38	using ::sg::fused::sm90::kDecNumTensors;
39	using ::sg::fused::sm90::apply_scalars;
40	using ::sg::fused::sm90::kPsiW1Off;
41	using ::sg::fused::sm90::kPsiB1Off;
42	using ::sg::fused::sm90::kPsiW2Off;
43	
44	struct TcScratch {
45	    torch::Tensor g_next, g_arrived, g_generation, workspace;
46	    int n_ctas = 0; int64_t ws_floats = 0;
47	};
48	
49	static int tc_effective_nctas(const torch::Tensor& params, int ncta_cap) {
50	    int dev = params.get_device(); int n_sms = 1;
51	    cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
52	    int n = n_sms;
53	    if (ncta_cap > 0 && ncta_cap < n) n = ncta_cap;
54	    return n;
55	}
56	
57	static TcScratch& tc_scratch_for(const torch::Tensor& params, int B, int nCTA) {
58	    static TcScratch s;
59	    const int T = B * dec::kSeq;
60	    const int64_t need = ::sg::fused::sm90::dec_tc_workspace_floats(T, B, nCTA);
61	    if (!s.g_next.defined()) {
62	        auto oi = torch::dtype(torch::kInt32).device(params.device());
63	        s.g_next = torch::zeros({1}, oi);
64	        s.g_arrived = torch::zeros({1}, oi);
65	        s.g_generation = torch::zeros({1}, oi);
66	    }
67	    s.n_ctas = nCTA;
68	    if (s.ws_floats < need) {
69	        s.workspace = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
70	        s.ws_floats = need;
71	    }
72	    return s;
73	}
74	
75	// Dispatch one TC step for the requested elementwise OptId. Mirrors
76	// mega_decoder_real_adamw_tc_launcher.cu's switch (the 5 elementwise arms only).
77	static cudaError_t launch_opt(int opt_id, PersistentContext ctx, float* params,
78	                              DecoderTokenCtx tok, float* grad, float lr, int step,
79	                              FusedOptState st, cudaStream_t stream, int nCTA) {
80	    switch (static_cast<OptId>(opt_id)) {
81	        case OptId::AdamW:
82	            return ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::AdamW>(
83	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
84	        case OptId::Lion:
85	            return ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::Lion>(
86	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
87	        case OptId::Grokfast:
88	            return ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::Grokfast>(
89	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
90	        case OptId::GrokAdamW:
91	            return ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::GrokAdamW>(
92	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
93	        case OptId::NeuralGrok:
94	            return ::sg::fused::sm90::launch_fused_decoder_megakernel_tc<OptId::NeuralGrok>(
95	                ctx, params, tok, grad, lr, step, st, stream, nCTA);
96	        default:
97	            return cudaErrorInvalidValue;   // out-of-scope opt for this elementwise driver
98	    }
99	}
100	
101	static std::vector<torch::Tensor> tc_train_step_opt(
102	        int64_t opt_id,
103	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
104	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
105	        double weight_decay, double bc1, double bc2, int64_t step,
106	        double alpha, double lamb, double gamma, int64_t ncta_cap) {
107	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
108	    TORCH_CHECK(params.numel() == kDecTotalElems, "params must be the flat decoder blob (", kDecTotalElems, ")");
109	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
110	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
111	    const int B = (int)targets.numel();
112	    TORCH_CHECK(tokens.numel() == (int64_t)B * dec::kSeq, "tokens must be [B,kSeq]");
113	    TORCH_CHECK((B % 16) == 0, "TC path requires B % 16 == 0");
114	    const int64_t total = kDecTotalElems;
115	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
116	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
117	
118	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
119	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
120	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
121	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
122	
123	    PersistentContext ctx{
124	        sc.g_next.data_ptr<int>(),
125	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
126	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
127	        kDecNumTensors, 0u};
128	
129	    // Bind [m | v | extra] over the SAME state buffer (launcher lines 170-176).
130	    float* m = state.data_ptr<float>();
131	    float* const extra_slice = m + 2 * total;
132	    FusedOptState st;
133	    st.exp_avg = m;
134	    st.exp_avg_sq = m + total;
135	    st.ema = extra_slice;                       // grokfast/grokadamw slow-grad EMA
136	    st.psi_W1 = extra_slice + kPsiW1Off;        // NeuralGrok psi-net pack head
137	    st.psi_b1 = extra_slice + kPsiB1Off;
138	    st.psi_W2 = extra_slice + kPsiW2Off;
139	
140	    // LIVE scalars (not inert defaults): bc1/bc2 drive Adam bias-correction; alpha/
141	    // lamb/gamma drive grokfast/grokadamw/neuralgrok. Pass via FusedScalars then
142	    // apply_scalars (the launcher's apply_scalars(st, scalars) path).
143	    FusedScalars scal;
144	    scal.lr = (float)lr; scal.beta1 = (float)beta1; scal.beta2 = (float)beta2;
145	    scal.eps = (float)eps; scal.wd = (float)weight_decay;
146	    scal.bc1 = (float)bc1; scal.bc2 = (float)bc2;
147	    scal.alpha = (float)alpha; scal.lamb = (float)lamb; scal.gamma = (float)gamma;
148	    apply_scalars(st, scal);
149	    st.lr = (float)lr;
150	
151	    DecoderTokenCtx tok;
152	    tok.tokens = tokens.data_ptr<int>();
153	    tok.targets = targets.data_ptr<int>();
154	    tok.B = B;
155	    tok.workspace = sc.workspace.data_ptr<float>();
156	    tok.loss_out = loss_dev.data_ptr<float>();
157	
158	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
159	    cudaError_t err = launch_opt((int)opt_id, ctx, params.data_ptr<float>(), tok,
160	                                 grad.data_ptr<float>(), (float)lr, (int)step, st, stream, nCTA);
161	    TORCH_CHECK(err == cudaSuccess, "TC megakernel launch failed (opt_id=", opt_id, "): ",
162	                cudaGetErrorString(err));
163	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
164	    return {loss_dev.to(torch::kCPU), grad};
165	}
166	
167	PYBIND11_MODULE(TORCH_EXTENSION_NAME, mm) {
168	    mm.def("tc_train_step_opt", &tc_train_step_opt,
169	           "OptId-generic TC decoder fwd+bwd+opt step (elementwise opts); returns (loss, grad)",
170	           pybind11::arg("opt_id"),
171	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
172	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
173	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
174	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"),
175	           pybind11::arg("alpha") = 0.98, pybind11::arg("lamb") = 2.0,
176	           pybind11::arg("gamma") = 0.0, pybind11::arg("ncta_cap") = 0);
177	    mm.attr("TOTAL") = (int)kDecTotalElems;
178	    mm.attr("D") = (int)::sg::fused::sm90::SG_DEC_D;
179	    mm.attr("LAYERS") = (int)::sg::fused::sm90::SG_DEC_LAYERS;
180	    mm.attr("VOCAB") = (int)::sg::fused::sm90::SG_DEC_VOCAB;
181	    mm.attr("SEQ") = (int)::sg::fused::sm90::SG_DEC_SEQ;
182	}
